#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""simtb.py <model.v> <top> <out.cpp> -- write the Verilator main of the random simulation of a
formal harness (the last step of the fallback ladder, scripts/sim.sh).

Every input of the harness except clk gets a random value in every cycle; the harness turns the
choices into a legal environment, as it does for the proofs. Addresses are biased towards the
small addresses of the formal configurations (below, inside and above the window), with some
out-of-window aliases (one high bit set) and some fully random ones; the reset request is rare.
The simulation runs in runs of a fixed length, each with its own seed (the seed also chooses the
tracked address and the free initial state)."""
import re, sys

model, top, out = sys.argv[1], sys.argv[2], sys.argv[3]
text = open(model).read()
m = re.search(r'^module\s+' + re.escape(top) + r'\b(.*?)^endmodule', text, re.S | re.M)
if not m:
    sys.exit(f'simtb.py: module {top} not found in {model}')
ports = []
for pm in re.finditer(r'^\s*input\s+wire\s*(?:\[(\d+):0\])?\s*(\w+)\s*;', m.group(1), re.M):
    width = int(pm.group(1)) + 1 if pm.group(1) else 1
    if pm.group(2) != 'clk':
        ports.append((pm.group(2), width))
if not ports:
    sys.exit('simtb.py: no inputs found')


def value(name, width):
    if width > 32:
        sys.exit(f'simtb.py: input {name} is wider than 32 bits')
    mask = '0xffffffffu' if width == 32 else hex((1 << width) - 1) + 'u'
    if name == 'in_rst':
        return 'chance(64)'
    if name.endswith('_adr'):
        return 'rnd_adr()'
    if name in ('in_f_cyc', 'in_f_stb'):
        return '(rnd() % 8 != 0)'
    if name in ('in_s_store',):
        return 'chance(4)'
    return f'(rnd() & {mask})'


assigns = '\n'.join(f'            top->{n} = {value(n, w)};' for n, w in ports)
open(out, 'w').write(f'''// generated by formal/cache/scripts/simtb.py for {top}
#include "V{top}.h"
#include "verilated.h"
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <memory>

static uint64_t s = 1;
static uint32_t rnd() {{ s ^= s << 13; s ^= s >> 7; s ^= s << 17; return (uint32_t)(s >> 11); }}
static uint32_t chance(uint32_t n) {{ return rnd() % n == 0; }}
static uint32_t rnd_adr() {{
    uint32_t r = rnd() % 16;
    if (r < 12) return rnd() % 48;                                 // below, in and above the window
    if (r < 14) return (rnd() % 48) | (1u << (6 + rnd() % 26));    // an alias: one high bit set
    return rnd();
}}

int main(int argc, char** argv) {{
    if (argc < 4) {{ std::fprintf(stderr, "usage: %s <cycles> <cycles per run> <seed>\\n", argv[0]); return 2; }}
    const long cycles = std::atol(argv[1]), per = std::atol(argv[2]);
    const uint64_t seed = std::strtoull(argv[3], nullptr, 10);
    long done = 0;
    int run = 0;
    while (done < cycles) {{
        const std::unique_ptr<VerilatedContext> ctx{{new VerilatedContext}};
        ctx->randReset(2);
        ctx->randSeed((int)(seed * 1000003u + (uint64_t)run));
        const std::unique_ptr<V{top}> top{{new V{top}{{ctx.get()}}}};
        s = (seed + 1) * 0x9E3779B97F4A7C15ull + (uint64_t)run * 2654435761ull + 1;
        top->clk = 0;
        top->eval();
        for (long c = 0; c < per && done < cycles; ++c, ++done) {{
{assigns}
            top->clk = 0;
            ctx->timeInc(1);
            top->eval();
            top->clk = 1;
            ctx->timeInc(1);
            top->eval();
            if (ctx->gotFinish()) {{ std::printf("SIM FAIL run %d cycle %ld (seed %llu)\\n", run, c, (unsigned long long)seed); return 1; }}
        }}
        top->final();
        ++run;
    }}
    std::printf("SIM PASS %ld cycles in %d runs (seed %llu)\\n", done, run, (unsigned long long)seed);
    return 0;
}}
''')
